{
  "defaults": {
    "hei_visible": false,
    "creative_visible": false
  },
  "rules": [
    {
      "name": "Show common chemistry",
      "match": { "molecule_tags": ["example:common"] },
      "exclude": { "ids": ["example:experimental_sample"] },
      "set": { "hei_visible": true, "creative_visible": true }
    },
    {
      "name": "Start polymer viewers with twelve units",
      "match": { "classifications": ["polymer"] },
      "set": { "polymer_preview_units": 12 }
    }
  ]
}
